    /// <summary>Stores texts in <see cref="AppLanguage"/> order so lookups can index by the enum.</summary>
    private static string[] Entry(string en, string pl, string uk)
    {
        var texts = new string[AppLanguages.All.Count];
        texts[(int)AppLanguage.En] = en;
        texts[(int)AppLanguage.Pl] = pl;
        texts[(int)AppLanguage.Uk] = uk;
        return texts;
    }
